using System.Security.Cryptography;using Finora.Application;using Finora.Domain;using Finora.Shared;namespace Finora.App;public sealed class MauiAppSettingsService:IAppSettingsService{public string DefaultCurrency{get=>Preferences.Get(nameof(DefaultCurrency),"INR");set=>Preferences.Set(nameof(DefaultCurrency),value);}public string Locale{get=>Preferences.Get(nameof(Locale),System.Globalization.CultureInfo.CurrentCulture.Name);set=>Preferences.Set(nameof(Locale),value);}public int FinancialMonthStartDay{get=>Preferences.Get(nameof(FinancialMonthStartDay),1);set=>Preferences.Set(nameof(FinancialMonthStartDay),Math.Clamp(value,1,28));}public bool PrivacyMode{get=>Preferences.Get(nameof(PrivacyMode),false);set=>Preferences.Set(nameof(PrivacyMode),value);}public bool HideAmountsOnLaunch{get=>Preferences.Get(nameof(HideAmountsOnLaunch),false);set=>Preferences.Set(nameof(HideAmountsOnLaunch),value);}public ThemePreference Theme{get=>Enum.TryParse<ThemePreference>(Preferences.Get(nameof(Theme),ThemePreference.System.ToString()),out var v)?v:ThemePreference.System;set=>Preferences.Set(nameof(Theme),value.ToString());}public bool ReducedMotion{get=>Preferences.Get(nameof(ReducedMotion),false);set=>Preferences.Set(nameof(ReducedMotion),value);}public bool BackupRemindersEnabled{get=>Preferences.Get(nameof(BackupRemindersEnabled),true);set=>Preferences.Set(nameof(BackupRemindersEnabled),value);}public bool OnboardingComplete{get=>Preferences.Get(nameof(OnboardingComplete),false);set=>Preferences.Set(nameof(OnboardingComplete),value);}public int AutoLockMinutes{get=>Preferences.Get(nameof(AutoLockMinutes),5);set=>Preferences.Set(nameof(AutoLockMinutes),Math.Clamp(value,1,60));}public bool LocalPremiumDemoEnabled{get=>Preferences.Get(nameof(LocalPremiumDemoEnabled),false);set=>Preferences.Set(nameof(LocalPremiumDemoEnabled),value);}}
public sealed class MauiAppLockService:IAppLockService{const string S="finora.pin.salt",H="finora.pin.hash",F="finora.pin.failures",L="finora.pin.lockUntil";public TimeSpan RemainingLockout{get{var u=DateTimeOffset.FromUnixTimeSeconds(Preferences.Get(L,0L));return u>DateTimeOffset.UtcNow?u-DateTimeOffset.UtcNow:TimeSpan.Zero;}}public async Task<bool>HasPinAsync()=>!string.IsNullOrEmpty(await SecureStorage.Default.GetAsync(H));public async Task<Result>SetPinAsync(string pin){if(pin.Length is <4 or >12||pin.Any(c=>!char.IsDigit(c)))return Result.Failure("PIN must contain 4–12 digits.");var salt=RandomNumberGenerator.GetBytes(16);var hash=Rfc2898DeriveBytes.Pbkdf2(pin,salt,150000,HashAlgorithmName.SHA256,32);await SecureStorage.Default.SetAsync(S,Convert.ToBase64String(salt));await SecureStorage.Default.SetAsync(H,Convert.ToBase64String(hash));Preferences.Remove(F);Preferences.Remove(L);CryptographicOperations.ZeroMemory(hash);return Result.Success();}public async Task<bool>VerifyPinAsync(string pin){if(RemainingLockout>TimeSpan.Zero)return false;var sr=await SecureStorage.Default.GetAsync(S);var hr=await SecureStorage.Default.GetAsync(H);if(sr is null||hr is null)return true;var a=Rfc2898DeriveBytes.Pbkdf2(pin,Convert.FromBase64String(sr),150000,HashAlgorithmName.SHA256,32);var e=Convert.FromBase64String(hr);var ok=CryptographicOperations.FixedTimeEquals(a,e);CryptographicOperations.ZeroMemory(a);CryptographicOperations.ZeroMemory(e);if(ok){Preferences.Remove(F);Preferences.Remove(L);return true;}var failures=Preferences.Get(F,0)+1;Preferences.Set(F,failures);if(failures>=5)Preferences.Set(L,DateTimeOffset.UtcNow.AddMinutes(Math.Min(30,1<<Math.Min(5,failures-5))).ToUnixTimeSeconds());return false;}public Task ClearPinAsync(){SecureStorage.Default.Remove(S);SecureStorage.Default.Remove(H);Preferences.Remove(F);Preferences.Remove(L);return Task.CompletedTask;}}
